# Blocks are written as connected lessons. Numeric datasets are fictional and
# original; each item below supplies its own figures rather than depending on notes.
B = {
 '01': [
 ('definition', 'What development means', "Development is improvement in people's quality of life across economic, social, political and environmental dimensions. Economic development concerns productive opportunities and material resources. Social development concerns conditions such as health, education, shelter and adequate food. Political development concerns people's ability to participate, exercise rights and hold decision makers accountable. Environmental development includes improving living conditions while protecting the resources on which people depend.", ['01-00']),
 ('worked_application', 'A project can have several effects', "Consider an invented settlement where a new workshop offers paid jobs but releases dirty water into the stream used by households. More production and earnings are possible economic gains. Unsafe water is an environmental and social cost. Calling the project development merely because output rises overlooks those costs. A useful assessment asks who gains, who loses and whether the gains can last. If a treatment system removes the waste and can be maintained, jobs and cleaner water may be achieved together. If the workshop cannot afford to maintain that system, its installation alone does not settle the issue.", ['01-00']),
 ('cross_link', 'Link the dimensions', "This distinction underlies the rest of the subject. Production in Topic 3.1 explains how goods and services are created. Health in Topic 7.2 and education in Topic 7.3 show why services matter to people's lives. When considering any new activity, connect its economic effect to at least one effect on people or their environment. A higher money income is evidence about one dimension; it is not a complete description of development.", ['01-00'])],
 '02': [
 ('plain_explanation', 'World patterns and differences within countries', "Development varies across the world and within individual countries. Broad historical patterns place many higher-income industrial economies in Europe, North America and parts of East Asia, while many lower-income economies are found in sub-Saharan Africa and parts of Asia. These are broad geographical patterns, not a current classification list or a claim about every country in a continent. High-income economies also occur outside those regions. Differences within a country can be large: an urban area may have a hospital and reliable water while a remote community has neither. A national average cannot locate those differences.", ['02-00', '02-01']),
 ('comparison', 'Developed, developing, LEDC and MEDC', "Developed and developing describe relative levels of development in a simplified way. More developed economies commonly have higher average incomes and wider access to services, but deprivation can persist in them. Developing covers countries with very different resources and experiences; it does not mean that nothing has developed. LEDC means less economically developed country and MEDC means more economically developed country. The economic emphasis matters. A higher income grouping does not show whether rights are protected, water is safe or income is shared equally. Use a label to introduce a comparison, then support that comparison with the indicator that actually answers the question.", ['02-01', '02-02']),
 ('comparison', 'Industrialised and less industrialised economies', "Industrialisation is growth in the importance and capacity of industrial production within an economy. Industrialised describes an economy with substantial industrial capacity; less industrialised describes relatively less. The existence of one factory does not settle the classification. Industrialisation can expand production, paid work and opportunities to learn technical skills. Its effect on living standards also depends on wages, safety, access to those jobs and environmental damage. An economy with a large service sector may still have substantial industrial capacity. Economic structure and quality of life are related questions, but neither is a complete substitute for the other.", ['02-03']),
 ('comparison', 'Capitalism and communism', "Capitalism emphasises private ownership of productive resources and market decisions about production and exchange. Communism as an economic ideal involves common ownership of productive resources; economies described as communist have generally relied heavily on state ownership and central planning. These descriptions concern ownership and decision making. They are not names for rich and poor. In practice, an economy may combine private shops, state services and public regulation. Establish the ownership arrangement from the evidence rather than assigning a development level from its label. Political institutions and economic arrangements also need to be examined separately.", ['02-04', '02-00']),
 ('plain_explanation', 'Newly industrialised countries', "A newly industrialised country, or NIC, has undergone substantial, relatively recent industrial expansion and structural change. Manufacturing and industrial employment become more important. The term is used in historical accounts of development and has no single permanent membership list. For this topic, understand the change the term describes rather than memorising a supposed up-to-date list. Expanding industry may create employment and exports while some households remain poor. To describe development, ask about the effects on income and living conditions as well as the change in production.", ['02-05']),
 ('interpretation', 'Reading an original comparison', "In a fictional same-year comparison, Region A has income per person of N$90,000 and 95% safe-water access; Region B has N$25,000 and 60% access. Region A combines higher average income with wider water access: income is N$65,000 higher and access is 35 percentage points higher. Those two observations support a difference in both economic resources and a living-condition indicator. They do not establish the political system or prove that income caused water access. A figure describes what was measured. A relationship links relevant figures without claiming more than they establish.", ['02-00', '02-01', '02-02']),
 ('cross_link', 'Keep classifications separate', "Topic 4.1 develops industrialisation and its consequences. The indicators in the next lesson give evidence for comparing development. When reading a source, first identify whether its labels concern income, industry or ownership. Then choose evidence relevant to the comparison. This avoids treating all three classifications as interchangeable.", ['02-00', '02-03', '02-04', '02-05'])],
 '03': [
 ('definition', 'Indicators are evidence', "An indicator is a measurable feature used as evidence about a wider condition; one indicator seldom gives a complete account of development. An environmental measure describes environmental conditions; a social measure describes people's living conditions; a political measure concerns participation or rights; an economic measure concerns productive resources, output or income. Check the definition, date, unit and population before comparing values. A percentage and a total answer different questions. Two measures can move together without one being proven to cause the other.", ['03-00']),
 ('interpretation', 'Environmental evidence', "Environmental indicators include the share of households using safe water, a measure of air pollution or an area of forest lost. Interpret the direction: more safe-water access is generally an improvement, while more harmful pollution is deterioration. In a fictional settlement, comparable annual records show safe-water access rising from 55% to 75% and unsafe water samples falling from 18 to 6 out of 30 tested. Access improves by 20 percentage points, and unsafe samples fall by 12. Together the observations support an improvement in water-related environmental conditions. They do not describe the settlement's air quality or identify the cause of the changes.", ['03-01', '03-00']),
 ('interpretation', 'Social evidence', "Social indicators include education, health, housing and service access. Literacy concerns the ability to read and write according to the measure used. Life expectancy is the average number of years a person at a stated age is expected to live under the mortality conditions used in the estimate; it is not a promise for an individual. Infant mortality rate records deaths before the first birthday per thousand live births for a stated period. In fictional District C, school participation rises from 70% to 85% and infant mortality falls from 40 to 25 per thousand live births. The combination supports improvement in education access and infant survival. Keep the units distinct: 15 percentage points and 15 deaths per thousand live births are not the same measure.", ['03-02', '03-00']),
 ('interpretation', 'Political evidence', "Political development concerns opportunities to participate and influence decisions, rights and accountability. Indicators may include participation in a decision process or evidence of access to it. In an invented community election with 1,000 eligible adults in each period, participation rises from 400 to 700 adults, while the number of neighbourhoods able to use an accessible meeting venue rises from two of five to five of five. Wider access accompanies higher participation. Counts from a meeting alone would not establish that rights are protected or that everyone had a free choice. Identify what the source actually measures and combine complementary observations rather than treating one statistic as a complete political judgement.", ['03-03', '03-00']),
 ('interpretation', 'Economic evidence', "Economic indicators can include income per person and employment. In fictional areas D and E, annual income per person is N$30,000 and N$45,000 respectively; employment among a consistently defined working-age population is 50% and 65%. E combines N$15,000 more average income with employment 15 percentage points higher. This supports a stronger position on those two measures. It does not show how much the lowest-income households receive or the quality of available jobs. Comparable definitions matter: changing the age range or what counts as employment can change the apparent pattern.", ['03-04', '03-00']),
 ('misconception', 'National totals and per-person figures', "A national total is the amount for the whole country. A per-person figure divides a total by population. GNP of N$120 million shared across 6,000 people gives N$20,000 per person for that period. A learner who calls the N$20,000 figure the national total has confused the two measures. GNI per person is also an average, rather than the income received by the whole nation. The separating test is whether the national measure has been divided by population. Neither average means that each person actually receives that amount. These examples explain the total-versus-average distinction, without treating different national accounting labels as interchangeable in every dataset.", ['03-04', '04-00']),
 ('worked_application', 'Combine dimensions without hiding a conflict', "Two fictional areas each have annual income per person of N$40,000. Area F has 90% safe-water access and a 20-minute average journey to a clinic; Area G has 50% access and an 80-minute journey. The equal income averages conceal differences in environmental and social access. Area F has water access 40 percentage points higher and a clinic journey 60 minutes shorter. Those differences justify examining service access separately from income. They do not prove that Area F is better on every aspect of development, since the data says nothing about participation or income distribution.", ['03-00', '03-01', '03-02', '03-04']),
 ('cross_link', 'Choose the measure for the question', "Health in Topic 7.2 and education in Topic 7.3 explain mechanisms behind social indicators. Research in Topic 10.1 explains how data is collected and assessed. To interpret a source, name the measured dimension, compare relevant observations with their units, and state the relationship they support. Add a limitation when the question needs a wider judgement, rather than allowing a caution to replace the required description.", ['03-00', '03-01', '03-02', '03-03', '03-04'])],
 '04': [
 ('definition', 'GNP and the per-person measure', "GNP is the value of final output attributable to a country's residents over a period, including net income from abroad. Distinguish the national total from a per-person figure. GNP per person is GNP divided by the population; an average that does not show how income is distributed. Use the same period and compatible currency units in a comparison. A larger population can produce a larger total without having more resources per person.", ['04-00']),
 ('worked_calculation', 'Show the division and the unit', "For a fictional country, annual GNP is N$240 million and population is 12,000. GNP per person = N$240,000,000 ÷ 12,000 = N$20,000 per person per year. Write out the millions before dividing, or keep a consistent power-of-ten method. This answer is an average, not the wage of a typical worker. If another fictional country has GNP of N$300 million and 30,000 residents, its average is N$10,000 per person per year despite its larger total.", ['04-00']),
 ('evaluation', 'Use it for an appropriate judgement', "GNP per person helps compare average economic resources, but cannot directly show housing, rights, health or pollution. Suppose a planning team must identify need for water support. Fictional Area H has average annual GNP per person of N$50,000 and 40% safe-water access; Area J has N$30,000 and 85% access. An income-only rule would prioritise J. For the specific aim of improving water access, H's much lower access provides a stronger reason to investigate its need. The income figures remain useful for understanding resources, but are insufficient for this allocation. Distribution also matters: a high average may coexist with many poor households.", ['04-00']),
 ('cross_link', 'Go beyond one average', "The next lesson compares living conditions; HDI and MPI then combine several dimensions. These measures supplement the economic information rather than making its limitations disappear.", ['04-00'])],
 '05': [
 ('plain_explanation', 'A pattern across living conditions', "Higher development is commonly associated with higher income per person, longer life expectancy and wider education and health access. Adequate housing includes shelter and access to essential services; diet concerns sufficient and varied food as well as the ability to buy it. Job opportunities matter through earnings, stability, safety and skills. A change from agriculture towards industrial and service employment can accompany development, but the sector name alone says little about wages or working conditions. Population growth also varies. It should be described from the source, rather than assumed from a country label.", ['05-00']),
 ('interpretation', 'A fictional comparison', "In a same-year synthetic table, Country K has annual income per person of N$22,000, life expectancy of 61 years and 58% of households with a basic sanitation service. Country L has N$68,000, 76 years and 91%. L combines higher income with longer life expectancy and wider sanitation access. The income difference is N$46,000, life expectancy is 15 years longer and sanitation access is 33 percentage points higher. The pattern spans economic and social conditions. It does not describe income inequality within either country. Nor does it justify a stereotype about an individual resident's diet, occupation or health.", ['05-00']),
 ('cross_link', 'Describe people as well as production', "Population in Topic 7.1, health in Topic 7.2 and education in Topic 7.3 provide explanations for these patterns. Start with what a table shows, select the relevant features, and distinguish a general association from a claim about every person. A useful comparison links the same characteristic across the two places.", ['05-00'])],
 '06': [
 ('definition', 'Human Development Index', "HDI is a composite measure combining health, education and income dimensions of human development; it does not capture every aspect of development. Composite means that several components are brought together. This helps a comparison move beyond national income alone. A higher comparable HDI indicates a higher combined level of achievement in its included dimensions. It does not mean that each household has the same standard of living or that environmental and political conditions have been fully measured.", ['06-01', '06-00']),
 ('definition', 'Multidimensional Poverty Index', "MPI is a measure of overlapping deprivations in health, education and living standards; it differs from an income-only poverty measure. Deprivation means a lack in a relevant condition, such as an essential service. The overlap matters: disadvantages can occur together in the same households. A lower comparable MPI indicates less multidimensional poverty. This is a different direction from HDI, where a higher value indicates higher achievement. Do not interpret a higher MPI as higher development simply because the number is larger.", ['06-02', '06-00']),
 ('interpretation', 'Read the two indices together', "In an original fictional comparison made using consistent methods, Country M has HDI 0.72 and MPI 0.08; Country N has HDI 0.55 and MPI 0.24. M combines a higher HDI with a lower MPI. The HDI difference is 0.17 and MPI difference is 0.16. Together these support higher combined human development and less multidimensional poverty in M. Do not call either difference a percentage change or assume it tells how many people lack a service. The indices summarise different information and are not subtracted from each other. They help reveal why income alone is incomplete, but a national summary still needs more detailed evidence about particular groups.", ['06-00', '06-01', '06-02']),
 ('worked_application', 'What the measures can guide', "If two places have similar average incomes but different school participation and health conditions, the extra dimensions matter to a comparison of human development. If the question concerns households experiencing several disadvantages together, MPI addresses that issue more directly than an income average. Select a measure by the question it can answer. A local decision about a particular water point still needs local access and cost evidence; an index alone cannot locate the repair or establish its feasibility.", ['06-00', '06-01', '06-02']),
 ('cross_link', 'Use dimensions, not a complicated formula', "Health and education are developed in Topics 7.2 and 7.3. Here, explain what the indices represent, their directions and their limits. Calculating a full HDI or MPI from component data is outside this lesson's teaching depth.", ['06-00', '06-01', '06-02'])],
 '07': [
 ('plain_explanation', 'Factors interact', "Development reflects interacting historical, political, social, resource and economic factors. A mineral deposit may provide an opportunity, but machinery, transport, skills and public decisions influence whether it benefits people. A barrier can also persist after the event that created it. Explain a factor by tracing a mechanism: identify the condition, show how it changes an opportunity or constraint, then connect that change to people's lives. Avoid treating a continent, culture or resource as a fixed destiny.", ['07-00', '07-04']),
 ('analysis_chain', 'Historical influences', "Past arrangements can shape present access to land, schooling and transport. In an invented region, a railway was built to carry ore directly to a port, while nearby farming settlements were left without feeder roads. Farmers now have produce to sell but cannot afford the slow journey to the railway. The inherited transport layout limits market access, so produce may remain unsold and farm income constrained. The explanation connects a historical pattern to a present mechanism. A road investment could reduce that constraint, but only if it can be maintained and farmers have buyers. History influences opportunities; it does not prevent choices that alter them.", ['07-01', '07-00']),
 ('analysis_chain', 'Political decisions and implementation', "Public decisions influence where resources go and whether services function. In a fictional district, a clinic budget is approved, but money intended for repairs is diverted and the roof remains damaged. Rain then closes the treatment room. The development problem is not merely a low budget: failed use of allocated funds prevents the facility operating. Accountability and repair oversight may help convert available resources into service access. A general claim that any one political label guarantees development misses the role of specific decisions, implementation and scrutiny.", ['07-02']),
 ('analysis_chain', 'Social opportunities', "Education can develop skills, and health can affect people's ability to learn and work. Access is shaped by barriers such as distance, cost or exclusion. In an invented settlement, skilled training places are available and a workshop is seeking trained workers, but afternoon sessions clash with learners' caring duties. Changing session times could allow more of those learners to attend, gain the relevant skill and apply for the available work. The job opportunities and available training are both material facts: changing the timetable would not by itself create jobs where none exist. Avoid blaming a group for barriers that the evidence identifies in its circumstances.", ['07-03']),
 ('analysis_chain', 'Resources and their use', "Natural resources are opportunities with conditions. In a fictional farming area, productive soil is available but a damaged water pump prevents irrigation during a dry period. Repairing the pump can help the soil support crops if the water supply is sufficient and withdrawals remain sustainable. In a different case, mineral earnings might finance school buildings, yet benefits may be limited if earnings leave the region or pollution damages water. State how resources are used and who benefits; naming a mineral is not an explanation of development.", ['07-04']),
 ('analysis_chain', 'Economic bottlenecks', "Finance, equipment, infrastructure and markets affect production and earnings. An invented sewing workshop has working machines, trained workers and confirmed orders, but lacks N$2,000 for cloth. Finance for cloth would remove the stated input shortage, allowing existing resources to meet the orders and earn revenue. Buying another machine would leave the cloth shortage unresolved. The consequence is conditional on the facts: without demand, more cloth would not establish that output could be sold. This is why a developed explanation uses the actual constraint rather than a memorised claim that any investment increases development.", ['07-05']),
 ('worked_application', 'Combine factors in a new case', "Suppose a fictional rural processing group has a reliable water supply and trained workers, but an impassable road prevents delivery of its products. The resource and social opportunities exist, yet the economic transport barrier prevents sales. Repairing that connection could allow income to be earned if buyers remain available. This case shows interaction: strengths in one dimension do not cancel a binding constraint elsewhere. To test an explanation, ask whether removing the proposed cause would change the outcome under the supplied conditions.", ['07-00', '07-03', '07-04', '07-05']),
 ('cross_link', 'Carry mechanisms into the subject', "Production in Topic 3.1, industrialisation in Topic 4.1 and rural development in Topic 5.1 revisit these connections. Public choices, social access and resources should be linked to a concrete mechanism and a development consequence. A well-supported explanation is more useful than a long list of factors with no connection between them.", ['07-00', '07-01', '07-02', '07-03', '07-04', '07-05'])]
}

# n: (prompt, model answer, item-specific indicative guidance). No copied papers.
Q = {
 1: ("Define development.", C['01-00'][0][1], ['Meaning: improvement in quality of life, covering the economic, social, political and environmental dimensions. Accept a precise equivalent formulation.']),
 2: ("Suggest an improvement to a fictional workshop project that creates paid jobs but discharges untreated waste into the settlement's drinking-water stream. Explain why your change supports development.", 'Install and maintain a suitable waste-treatment system so jobs can continue while water contamination is reduced. Maintenance and safe disposal are needed for the environmental and health gains to last.', ['Context: address the stated contaminated stream.', 'Reason: connect a feasible waste-control action to safer water while retaining the economic opportunity. Do not require the learner to name a particular treatment technology.']),
 3: ("Describe two different features used to classify world development patterns.", 'Income-related groupings describe relative economic development. Industrialised and less industrialised describe the importance and capacity of industrial production.', ['Feature: identify and describe two distinct classification dimensions; ownership arrangements are also a valid dimension. Do not award a second feature for restating the same income label.']),
 4: ("Describe the development relationship in this original fictional comparison: Region A has annual income per person N$90,000 and safe-water access 95%; Region B has N$25,000 and 60% respectively.", 'The higher-income region also has wider safe-water access. A has N$65,000 more income per person and access 35 percentage points higher than B.', ['Evidence: use the income and water observations accurately.', 'Relationship: link higher income with wider access in this comparison; a causal claim is not required.']),
 5: ("Describe two common characteristics of a more developed economy compared with a less developed economy.", 'A more developed economy commonly has higher average income and wider access to education and health services. These are broad tendencies rather than descriptions of every resident.', ['Feature: two relevant relative characteristics, such as income and service access. Avoid implying universal living conditions.']),
 6: ("Describe what LEDC and MEDC indicate about a country.", 'LEDC means less economically developed country and MEDC means more economically developed country. They are relative economic groupings rather than complete measures of well-being.', ['Feature: correct less/more economic distinction. Do not interpret the terms as direct measures of political rights.']),
 7: ("Describe the distinction between industrialised and less industrialised economies.", 'An industrialised economy has substantial industrial productive capacity; a less industrialised economy has relatively less. The distinction concerns economic structure rather than the mere presence of a factory.', ['Feature: relative industrial capacity or importance, with the distinction clearly paired.']),
 8: ("Describe the difference in productive-resource ownership emphasised by capitalism and by the communist economic ideal.", 'Capitalism emphasises private ownership, while the communist ideal involves common ownership of productive resources. Actual economies may combine arrangements.', ['Feature: private versus common ownership. Accept a correctly qualified description of heavy state ownership in economies historically described as communist.']),
 9: ("Describe two features of a newly industrialised country.", 'It has undergone substantial, relatively recent industrial expansion. Its economic structure has changed as industrial production and employment have become more important.', ['Feature: industrial expansion and structural change; neither feature requires a claim that poverty has disappeared.']),
 10: ("Explain why more than one indicator is useful when measuring development.", 'Development has several dimensions. An income figure shows economic resources but can conceal poor water access or health, so combining relevant measures gives a fuller account.', ['Reason: connect the multidimensional concept to information that one measure misses.']),
 11: ("Describe what this original fictional dataset reveals beyond equal income averages: F and G each have annual income per person N$40,000; F has safe-water access 90% and a clinic journey of 20 minutes; G has 50% and 80 minutes.", 'Equal average income conceals better service access in F. F has safe-water access 40 percentage points higher and a clinic journey 60 minutes shorter than G.', ['Evidence: compare the two supplied service measures accurately.', 'Relationship: explain the contrast between equal income and unequal access.']),
 12: ("Describe the water-related environmental change in an original fictional settlement: safe-water access rises from 55% to 75%, while unsafe samples fall from 18 to 6 out of 30 tests in each period.", 'Water-related conditions improve on both measures. Access rises 20 percentage points and unsafe samples fall by 12 out of the same number tested.', ['Evidence: use both comparable measures.', 'Relationship: connect wider access and reduced contamination to the direction of environmental change.']),
 13: ("Describe the social-development pattern in original fictional District C: school participation rises from 70% to 85%, while infant mortality falls from 40 to 25 deaths per thousand live births.", 'Education participation and infant survival both improve. Participation rises 15 percentage points while infant mortality falls by 15 deaths per thousand live births.', ['Evidence: retain the different units for the two indicators.', 'Relationship: link both changes to improving social conditions; do not call the mortality difference a percentage-point change.']),
 14: ("Describe the participation pattern in this invented community election: 1,000 eligible adults in each period; voters increase from 400 to 700 and neighbourhoods with an accessible venue increase from two of five to five of five.", 'Participation rises from 40% to 70% while venue access expands to all five neighbourhoods. Wider access accompanies higher participation in this case.', ['Evidence: use both voter participation and venue access.', 'Relationship: link wider access with higher participation without treating the source as proof of all political rights.']),
 15: ("Describe the economic relationship in this original fictional comparison: D has annual income per person N$30,000 and employment 50%; E has N$45,000 and 65%, measured using the same working-age definition.", 'Higher employment accompanies higher income per person in E. E is 15 percentage points higher on employment and N$15,000 higher on average annual income.', ['Evidence: accurate paired comparisons with units.', 'Relationship: associate higher employment with higher average income in these data.']),
 16: ("Explain why GNP per person is more useful than total GNP for comparing average economic resources in countries with different populations.", 'Dividing GNP by population accounts for how many people share the national total. A larger total may reflect more people rather than more resources per person.', ['Reason: connect division by population to a meaningful average comparison.']),
 17: ("Explain which fictional area should be investigated first for water support if the aim is to improve access: H has annual GNP per person N$50,000 and safe-water access 40%; J has N$30,000 and 85%. Weigh an income-only rule against the supplied access evidence.", 'Investigate H first for the stated aim: only 40% have safe-water access compared with 85% in J. An income-only rule would prioritise J because its average is lower, but that would overlook H\'s much larger access gap. GNP per person remains useful for economic resources, yet access evidence is more directly relevant to this decision.', ['Judgement: a supported priority tied to improving water access.', 'Reason: weigh the conflicting income and access signals, explaining why the selected evidence fits the aim. Accept a conditional alternative if it genuinely addresses the criterion and both sources.']),
 18: ("Calculate annual GNP per person for a fictional country with annual GNP N$240 million and population 12,000. Show your working.", 'N$240,000,000 ÷ 12,000 = N$20,000 per person per year.', ['Working: divide the converted national total by the population.', 'Unit: N$ per person per year.']),
 19: ("State two living-condition characteristics commonly associated with higher development.", 'Longer life expectancy and wider access to education or health services.', ['Feature: two relevant living-condition characteristics; accept adequate housing, diet or essential-service access.']),
 20: ("Describe the development pattern in this original fictional same-year table: K has annual income per person N$22,000, life expectancy 61 years and sanitation access 58%; L has N$68,000, 76 years and 91%.", 'L combines higher average income with longer life expectancy and wider sanitation access. For example, income is N$46,000 higher and life expectancy 15 years longer; sanitation access is also 33 percentage points higher.', ['Evidence: accurate comparisons from at least two indicators.', 'Relationship: connect the economic and living-condition pattern; all three calculations are not compulsory for three marks.']),
 21: ("Explain why HDI and MPI add useful information to an income-only comparison of development.", 'They include health and education as well as other dimensions. HDI summarises achievement, while MPI captures overlapping deprivations, so differences hidden by similar income averages can be considered.', ['Reason: explain the additional dimensions or overlapping disadvantages rather than merely expanding the abbreviations.']),
 22: ("Describe the human-development pattern in this original fictional comparison using consistent methods: M has HDI 0.72 and MPI 0.08; N has HDI 0.55 and MPI 0.24.", 'M has both higher combined human development and less multidimensional poverty: its HDI is 0.17 higher and MPI 0.16 lower. The two indicators support the same broad direction despite their opposite scales of improvement.', ['Evidence: correctly compare both indices.', 'Relationship: higher HDI and lower MPI support a consistent development pattern.']),
 23: ("Define Human Development Index (HDI).", C['06-01'][0][1], ['Meaning: a composite measure combining health, education and income dimensions of human development.']),
 24: ("Define Multidimensional Poverty Index (MPI).", C['06-02'][0][1], ['Meaning: a measure of overlapping deprivations in health, education and living standards.']),
 25: ("Explain why having natural resources does not by itself guarantee development.", 'People also need capabilities, infrastructure and decisions that enable productive use and share the benefits. Resources may remain unused or their gains may be offset by depletion, pollution or exclusion.', ['Reason: develop one link between a condition on resource use and a development outcome.']),
 26: ("Explain the constraint on development in this invented processing group: it has reliable water and trained workers, but an impassable road prevents delivery to confirmed buyers.", 'The transport barrier prevents the group turning its water supply and skills into sales. Restoring a usable route could allow deliveries and earnings while buyers remain available, so the economic constraint limits the gains from existing resources and capabilities.', ['Mechanism: use the contrast between available inputs and blocked delivery.', 'Consequence: connect access to sales or earnings, conditional on usable transport and demand.']),
 27: ("Explain how history influences present farm incomes in an invented region where an old ore-to-port railway bypasses farming settlements and farmers with produce cannot afford the slow journey to it.", 'The inherited railway layout leaves farmers without an affordable market connection. Produce may remain unsold or transport costs absorb earnings, restricting farm income despite available output.', ['Mechanism: connect the inherited layout to present transport access.', 'Consequence: explain the effect on sales or income using the supplied produce and cost facts.']),
 28: ("Explain the development effect in an invented district where allocated clinic-repair money is diverted and rain closes the treatment room under its unrepaired roof.", 'Diversion prevents the funded repair being carried out. The damaged room then closes during rain, reducing treatment access even though resources had been allocated.', ['Mechanism: diverted resources prevent implementation.', 'Consequence: connect the unrepaired roof and rain to reduced health-service access.']),
 29: ("Explain how changing training times could support development in an invented settlement where afternoon sessions clash with caring duties and a workshop has vacancies for people with the skills taught.", 'Changing the times could let affected learners attend and gain the required skill. Because relevant vacancies exist, the new access could improve their employment opportunities and potential income.', ['Mechanism: connect the timetable barrier to access to training.', 'Consequence: link skills to the stated vacancies; attendance does not guarantee a job.']),
 30: ("Explain how repairing a pump could affect development in an invented area with productive soil, sufficient available water and crops failing because irrigation has stopped during a dry period.", 'Repair restores access to the available water, allowing the productive soil to support irrigated crops. Reduced crop losses could improve food supply or farm earnings if the pump and withdrawals can be maintained sustainably.', ['Mechanism: connect pump repair to the supplied water and soil resources.', 'Consequence: food or income gains follow reduced crop failure under the stated conditions.']),
 31: ("Explain which economic constraint should be removed first in an invented workshop with working machines, trained workers and confirmed orders but a shortage of N$2,000 for cloth.", 'Finance for cloth removes the missing-input constraint. The workshop can then use its existing workers and machines to fulfil the orders and earn revenue; another machine would leave the cloth shortage unresolved.', ['Mechanism: identify the binding finance/input shortage using the other available resources.', 'Consequence: connect cloth to fulfilling existing orders and earning revenue.']),
 32: ("Explain the error when a learner calls a fictional country's GNI per person of N$35,000 its total national income.", 'The learner has confused an average with a national total. Per person means the national measure has been divided by population; N$35,000 is an average, not the total for the whole country.', ['Error: national total confused with per-person average.', 'Distinction: use the division-by-population test; the average does not mean each individual receives that amount.'])
}

P = {
 'P01': (
  ['01-00', '03-00'],
  "State (a) two dimensions of development illustrated by this original fictional case [2]. Explain (b) why the factory's higher output alone does not establish an overall improvement in local development, using both supplied changes [4]. Case: output rises from 100 to 150 bags per week, but safe-water access falls from 80% to 50% after untreated waste enters the community's supply.",
  '(a) Economic and environmental development; social development is also relevant to safe water. (b) Production rises by 50 bags a week, supporting an economic gain, while safe-water access falls by 30 percentage points. The adverse water change means increased output coexists with worse living conditions. Overall improvement cannot be established from output alone; benefits and costs to people must be considered together.',
  ['Point (a), 2 marks: two relevant dimensions, accurately identified.', 'Development (b), up to 4 marks: use both the output increase and access deterioration to explain the conflict between dimensions and the inadequacy of an output-only conclusion. Reward a connected contrast; a generic list without using the source does not meet the analytical demand.']),
 'P02': (
  ['03-00', '04-00'],
  "Calculate (a) annual GNP per person for fictional Country R, showing working [2]. Explain (b) whether R's larger total GNP is a sound reason to prioritise S for a project whose stated aim is to reduce unsafe-water access, using the averages and access figures [4]. Original same-year data: R, GNP N$360 million, population 18,000, safe-water access 45%; S, GNP N$240 million, population 8,000, safe-water access 80%. The definitions and currency basis are comparable.",
  '(a) N$360,000,000 ÷ 18,000 = N$20,000 per person per year. (b) No. S has N$30,000 per person per year, so R\'s larger total actually accompanies a lower average. Moreover, 55% in R lack safe-water access compared with 20% in S. R therefore warrants priority investigation for the stated water aim. The figures establish average resources and access gaps, not final project costs or which particular households need support.',
  ['Evidence (a), 2 marks: accurate division and N$20,000 per person per year.', 'Meaning (b), up to 4 marks: compare the two averages, use the water-access evidence and give a connected reason for the priority under the stated aim. An income-only assertion or an unsupported recommendation is insufficient. Detailed project feasibility is not supplied; accept a conditional priority consistent with that limit.'])
}

def stamp(x):
    x['claims_seen'] = {cid: 1 for cid in x.get('claim_ids', [])}
    x['authored_hash'] = hashlib.sha256(_artefact_text(x).encode()).hexdigest()
    return x

def main():
    wo = read(TD / 'work_order.json')
    contract = read(TD / 'contract.json')
    claims = []
    by_obj = {}
    for suffix, entries in C.items():
        by_obj[suffix] = []
        for n, (kind, text) in enumerate(entries, 1):
            cid = f'CLM-6136-1.1-{suffix}-{n:02d}'
            by_obj[suffix].append(cid)
            claims.append({'claim_id': cid, 'objective_ids': [oid(suffix)], 'text': text,
              'claim_type': kind, 'provenance': 'generated_gap', 'evidence': [],
              'derived_from_claim_ids': [], 'revision': 1,
              'verification': {'status': 'unverified', 'method': 'Original Codex teaching synthesis from the approved conceptual scope; awaiting independent Claude Code review.', 'reviewer_id': None, 'reviewed_at': None, 'confidence': 0.9},
              'publishable': False, 'notes': ['Conceptual authoring claim; evidence IDs are not invented.']})
    dump(TD / 'claims/canonical_claim_ledger.json', {'ledger_id': 'LEDGER-6136-1.1', 'claims': claims})
    for spec in wo['content_units']:
        num = spec['sub_topic'].split('.')[-1]
        blocks = []
        for n, (kind, heading, text, suffixes) in enumerate(B[num], 1):
            blocks.append(stamp({'block_id': f'BLK-6136-1.1.{num}-{n:02d}', 'block_type': kind,
                'heading': heading, 'text': text, 'claim_ids': list(dict.fromkeys(c for s in suffixes for c in by_obj[s])),
                'context_tags': ['original conceptual teaching', 'synthetic examples where stated'],
                'assessment_objectives': ['A', 'B']}))
        wc = sum(len((b['heading'] + ' ' + b['text']).split()) for b in blocks)
        lo, hi = spec['word_budget']
        dump(TD / spec['file'], {'unit_id': spec['unit_id'], 'title': B[num][0][1],
          'objective_ids': spec['objective_ids'], 'level': 'NSSCO', 'core_status': 'core',
          'objective_type': 'integrated_development_lesson', 'depth_tier': 3,
          'word_budget': {'min': lo, 'target': (lo + hi) // 2, 'max': hi},
          'blocks': blocks, 'word_count': wc, 'qa_status': 'review_required',
          'notes': ['Lower allocation advisory under approved handover; concise integrated teaching of parent and retained members, without repeating each as a separate essay.']})
    items = []
    perf_specs = {x['slot']: x for x in read(WS / 'curriculum/performance-slot-specs.json')['slots']}
    for slot in wo['item_slots'] + wo['performance_tasks']:
        sid = slot['slot']; perf = 'item_type' in slot
        if perf:
            ps = perf_specs[sid]
            suffixes, prompt, answer, guidance = P[sid.rsplit('-', 1)[-1]]
            meta = ps
        else:
            n = int(sid.split('-')[-2]); prompt, answer, guidance = Q[n]
            suffixes = [slot['objective_id'].removeprefix('OBJ-6136-1.1.')]
            meta = slot
        selected = list(dict.fromkeys(c for s in suffixes for c in by_obj[s]))
        # Economic indicator cards explicitly use the parent total-versus-average
        # teaching in addition to their assigned objective.
        if not perf and int(sid.split('-')[-2]) == 32:
            selected += by_obj['03-04']
        item = {'item_id': sid, 'objective_ids': [oid(s) for s in suffixes], 'claim_ids': selected,
          'item_type': slot['item_type'] if perf else 'flashcard', 'subtype': slot.get('subtype'),
          'assessment_objectives': meta['assessment_objectives'], 'blooms_level': meta['blooms_level'],
          'command_word': meta['command_word'], 'mark_tariff': meta['mark_tariff'],
          'difficulty': slot.get('difficulty', 3), 'prompt': prompt, 'canonical_answer': answer,
          'marking_guidance': guidance + ['Original indicative practice guidance; not an official mark scheme.'],
          'context': {'sector': None, 'business_size': None, 'ownership': None,
                      'situation': 'Original fictional data where stated; otherwise conceptual recall.', 'facts': []},
          'prerequisite_item_ids': [], 'core_status': 'core', 'intentional_duplicate_group': None,
          'provenance': 'Original Codex authoring, 2026-10-20; pending independent Claude Code review.',
          'qa_status': 'review_required'}
        if slot.get('misconception_entry'): item['misconception_entry'] = slot['misconception_entry']
        items.append(stamp(item))
    assert len(items) == wo['planned_item_count']
    dump(TD / wo['output_files']['learning_items'], {'dataset_id': 'ITEMS-6136-1.1', 'topic_id': '1.1', 'items': items})
    dump(TD / 'authoring_notes.json', {'topic_id': '1.1', 'deviations': [
      {'from': 'Generated lower word allocations', 'to': 'Several integrated lessons are shorter; original budgets preserved for visible C-26 warnings.',
       'why': 'The approved handover makes minimum allocations advisory. Repeating related parent/member explanations to meet a word floor would dilute the lesson.'}],
      'limits': ['Claims remain unverified and not publishable pending independent review.', 'Synthetic datasets are teaching examples, not current country statistics.',
                 'No full HDI/MPI component formula, current country classification list or copied assessment source is taught.']})
    print(json.dumps({'topic': '1.1', 'claims': len(claims), 'units': len(wo['content_units']), 'items': len(items)}))

if __name__ == '__main__': main()
